#include "api_diagnostics.hpp"
#include <algorithm>
#include <map>
#include <mutex>
namespace scratchbird::engine::internal_api{namespace{std::mutex m;using D=scratchbird::engine::sblr::SblrSecRevokeDescriptorV1;std::map<std::string,D>live,used;std::string key(const D&v){return{(const char*)v.descriptor_evidence.data(),v.descriptor_evidence.size()};}EngineApiDiagnostic d(std::string c,std::string k){return MakeEngineApiDiagnostic(std::move(c),std::move(k),{});}bool tag(const EngineRequestContext&c,const char*t){return c.security_context_present&&std::find(c.trace_tags.begin(),c.trace_tags.end(),t)!=c.trace_tags.end();}}
SblrSecRevokeCoordinationResult CompileSblrSecRevokeDescriptor(const EngineRequestContext&c,const std::string&r,uint64_t o,uint64_t a){SblrSecRevokeCoordinationResult x;if(!tag(c,"private_sec_revoke_binder")||r!=c.statement_uuid.canonical||!o||!a){x.diagnostic=d("SBLR.OPERAND.INVALID","sblr.sec_revoke.coordination_invalid");return x;}x.descriptor.grant_uuid[0]=uint8_t(o);x.descriptor.grantee_uuid[0]=uint8_t(o+1);x.descriptor.target_object_uuid[0]=uint8_t(o+2);x.descriptor.expected_generation=o;x.descriptor.catalog_generation=o;x.descriptor.security_generation=o;x.descriptor.availability=a;x.descriptor.descriptor_evidence[0]=uint8_t(o);std::lock_guard l(m);live[key(x.descriptor)]=x.descriptor;x.ok=true;return x;}
SblrSecRevokeCoordinationResult ConsumeSblrSecRevokeDescriptor(const EngineRequestContext&c,const D&v){SblrSecRevokeCoordinationResult x;if(!tag(c,"private_sec_revoke")){x.diagnostic=d("SECURITY.ACCESS_DENIED","sblr.sec_revoke.hidden");return x;}std::lock_guard l(m);auto i=live.find(key(v));if(i==live.end()){x.diagnostic=d(used.count(key(v))?"MGA.TRANSACTION.STALE":"SECURITY.ACCESS_DENIED","sblr.sec_revoke.replay");return x;}if(c.query_cancellation_requested&&c.query_cancellation_requested()){x.diagnostic=d("PROCESS.CANCELLED","sblr.sec_revoke.cancelled");return x;}used[key(v)]=v;live.erase(i);x.ok=true;x.descriptor=v;return x;}}
